//! TypeScript tables written by `export-bindings`.
//!
//! Sources, each edited in one place:
//! - [`crate::vars::VAR_PATTERN`]
//! - [`crate::vars::builtins::BUILTIN_NAMES`]
//! - the `classify` match in `grpc/invoke/well_known.rs`

use std::path::Path;

use regex::Regex;

use crate::vars::builtins::BUILTIN_NAMES;
use crate::vars::VAR_PATTERN;

const WELL_KNOWN_RS: &str = include_str!("grpc/invoke/well_known.rs");

const HEADER: &str = "\
// AUTO-GENERATED by export-bindings. Do not edit.
// Regenerate: cargo run -p handshaker --bin export-bindings --features export-bindings
";

/// Repo-relative path and file text for each generated table.
pub fn generated_var_tables() -> [(&'static str, String); 3] {
    [
        ("src/features/vars/varGrammar.gen.ts", var_grammar_ts()),
        ("src/lib/wellKnown.gen.ts", well_known_ts()),
        ("src/features/vars/builtins.gen.ts", builtins_ts()),
    ]
}

/// Write the three tables under `repo_root` (the workspace root, not `src-tauri/`).
pub fn write_generated_var_tables(repo_root: &Path) -> std::io::Result<()> {
    for (rel, contents) in generated_var_tables() {
        let path = repo_root.join(rel);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        std::fs::write(path, contents)?;
    }
    Ok(())
}

fn var_grammar_ts() -> String {
    let literal = js_string_literal(VAR_PATTERN);
    format!(
        "{HEADER}
// Source: crates/handshaker-core/src/vars/mod.rs (`VAR_PATTERN`).

/** Rust `VAR_PATTERN`. The name is any non-empty run of non-brace characters. */
export const VAR_PATTERN_SOURCE = {literal};
"
    )
}

fn builtins_ts() -> String {
    let mut names = String::new();
    for name in BUILTIN_NAMES {
        names.push_str("  \"");
        names.push_str(name);
        names.push_str("\",\n");
    }
    format!(
        "{HEADER}
// Source: crates/handshaker-core/src/vars/builtins.rs (`BUILTIN_NAMES`).

export const BUILTIN_NAMES = [
{names}] as const;

export type BuiltinName = (typeof BUILTIN_NAMES)[number];

export function isBuiltinName(name: string): name is BuiltinName {{
  return (BUILTIN_NAMES as readonly string[]).includes(name);
}}
"
    )
}

fn well_known_ts() -> String {
    render_well_known(&classify_arms(WELL_KNOWN_RS))
}

fn render_well_known(arms: &[(String, String)]) -> String {
    let mut entries = String::new();
    for (name, variant) in arms {
        let shape = ts_shape(variant);
        entries.push_str("  \"");
        entries.push_str(name);
        entries.push_str("\": \"");
        entries.push_str(shape);
        entries.push_str("\",\n");
    }
    format!(
        "{HEADER}
// Source: crates/handshaker-core/src/grpc/invoke/well_known.rs (`classify`).

export type WktScalarShape = \"number\" | \"string\" | \"bool\";

export const SCALAR_WKT = {{
{entries}}} as const;

export function scalarWktShape(
  messageType: string | null | undefined,
): WktScalarShape | null {{
  if (!messageType) return null;
  return (SCALAR_WKT as Record<string, WktScalarShape>)[messageType] ?? null;
}}

export function isScalarWkt(fullName: string): boolean {{
  return Object.prototype.hasOwnProperty.call(SCALAR_WKT, fullName);
}}
"
    )
}

/// `"google.protobuf.X" => Variant` arms inside `fn classify`.
fn classify_arms(src: &str) -> Vec<(String, String)> {
    let start = src.find("pub(crate) fn classify(").expect("fn classify");
    let rest = &src[start..];
    let end = rest.find("\n}").expect("end of fn classify");
    let body = &rest[..end];
    let re = Regex::new(r#""(google\.protobuf\.[A-Za-z0-9]+)"\s*=>\s*([A-Za-z0-9]+)"#)
        .expect("arm regex");
    let arms: Vec<(String, String)> = re
        .captures_iter(body)
        .map(|caps| (caps[1].to_string(), caps[2].to_string()))
        .collect();
    assert!(
        !arms.is_empty(),
        "classify match has no google.protobuf arms"
    );
    arms
}

fn ts_shape(variant: &str) -> &'static str {
    match variant {
        "DoubleValue" | "FloatValue" | "Int64Value" | "UInt64Value" | "Int32Value"
        | "UInt32Value" => "number",
        "BoolValue" => "bool",
        "StringValue" | "BytesValue" | "Timestamp" | "Duration" | "FieldMask" => "string",
        other => panic!("no TS shape for scalar well-known variant {other}"),
    }
}

fn js_string_literal(raw: &str) -> String {
    format!("\"{}\"", raw.replace('\\', "\\\\"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn classify_match_lists_field_mask_among_twelve() {
        let arms = classify_arms(WELL_KNOWN_RS);
        assert_eq!(arms.len(), 12);
        assert!(arms
            .iter()
            .any(|(name, _)| name == "google.protobuf.FieldMask"));
    }

    #[test]
    fn dropping_field_mask_changes_the_generated_table() {
        let mut arms = classify_arms(WELL_KNOWN_RS);
        let before = arms.len();
        arms.retain(|(name, _)| name != "google.protobuf.FieldMask");
        assert_eq!(
            before,
            arms.len() + 1,
            "FieldMask arm missing from classify"
        );
        assert_ne!(
            render_well_known(&arms),
            well_known_ts(),
            "synthetic_wkt_drift_detected"
        );
    }

    #[test]
    fn generated_var_tables_match_committed_files() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        for (rel, expected) in generated_var_tables() {
            let path = root.join(rel);
            let actual = std::fs::read_to_string(&path)
                .unwrap_or_else(|err| panic!("read {}: {err}", path.display()));
            assert_eq!(
                actual, expected,
                "{rel} does not match the Rust source; run export-bindings and commit the generated file"
            );
        }
    }
}
